if (!root) return;

if (item < root->data) {
    avlDelete(root->left, item);
} else if (item > root->data) {
    avlDelete(root->right, item);
} else {
    TreeNode<int>* toDelete = root;
    if (!root->left || !root->right) {
        root = (root->left) ? root->left : root->right;
        delete toDelete;
    } else {
        TreeNode<int>* minRight = root->right;
        while (minRight->left) minRight = minRight->left;
        root->data = minRight->data;
        avlDelete(root->right, minRight->data);
    }
}

if (!root) return;

int balance = bstHeight(root->left) - bstHeight(root->right);

if (balance > 1) {
    if (bstHeight(root->left->left) >= bstHeight(root->left->right)) {
        avlRotateRight(root);
    } else {
        avlRotateLeft(root->left);
        avlRotateRight(root);
    }
} else if (balance < -1) {
    if (bstHeight(root->right->right) >= bstHeight(root->right->left)) {
        avlRotateLeft(root);
    } else {
        avlRotateRight(root->right);
        avlRotateLeft(root);
    }
}

